def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    lines = []
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            lines.append(([(r, c) for c in range(w)], row[0]))
    for c in range(w):
        vals = [grid[r][c] for r in range(h)]
        if len(set(vals)) == 1:
            lines.append(([(r, c) for r in range(h)], vals[0]))
    for cells, color in lines:
        if color > 0:
            for r, c in cells:
                out[r][c] = color - 1
    return out
